import {PARTS,MAKERS,FAMILIES,RARITIES,RARITY_COLORS,SLOT_DEFS,TACTICS,TARGETS,SECTORS,getPart,accepts,statsFor,missionInfo,enemyLoadout,VERSION} from './parts.js?v=1.7.0';
import {createBattle,tick,fastForward} from './simulation.js?v=1.7.0';
import {loadState,normalizeState,persist,unlockedMission,shopOffers,settleBattle} from './state.js?v=1.7.0';
import {MechScene,PAINTS} from './renderer.js?v=1.7.0';
import {analyzeBuild,weaponSlot} from './build-analysis.js?v=1.7.0';
import {fittingPanel,buildBrief,diagnosticPanel,debrief,weaponStatus,weaponComparisonPanel,weaponSalvageSummary} from './ui-components.js?v=1.7.0';
import {BattleAudio} from './audio.js?v=1.7.0';

const $=q=>document.querySelector(q),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Math.round(n).toLocaleString('ja-JP'),signed=n=>(n>0?'+':'')+(Number.isInteger(n)?n:n.toFixed(1));
const ICONS={
  hangar:'M3 9 12 3l9 6v12H3z M8 21V11h8v10 M7 8h10',
  missions:'M4 7h16v13H4z M8 7V4h8v3 M8 12h8 M8 16h5',
  shop:'M3 8h18l-2 12H5z M8 8l2-5h4l2 5 M8 12v4 M12 12v4 M16 12v4',
  catalog:'M4 3h7v8H4z M14 3h6v8h-6z M4 14h7v7H4z M14 14h6v7h-6z',
  body:'M7 3h10l4 5-2 10-7 3-7-3L3 8z M8 9h8 M9 14h6 M10 4v2h4V4',
  arm:'M8 3h8l3 5-3 4 2 7-4 2-5-7-3-3 2-8z M10 7h4 M10 13l4-1',
  legs:'M6 3h12v5l-3 2 4 10h-6l-1-8-1 8H5l4-10-3-2z',
  engine:'M7 3h10v4h3v10h-3v4H7v-4H4V7h3z M9 8h6v8H9z M1 10h3 M20 10h3',
  armor:'M12 2 3 6v6l3 6 6 4 6-4 3-6V6z M7 9l5 8 5-8',
  weapon:'M3 7h13v5H7l-2 6H2l2-6H3z M16 8h6v3h-6 M9 12v4h5v-4 M7 5h4v2',
  sword:'M4 20 18 3l3 1-1 3L7 20 M4 14l6 6 M3 21l3-3',
  missile:'M6 3h12v18H6z M9 7h1 M14 7h1 M9 12h1 M14 12h1 M9 17h1 M14 17h1',
  cannon:'M3 7h7v8H3z M10 8h12v6H10 M4 15v5h5l2-5 M15 6v10',
  punch:'M5 9V6h3V4h3v1h3v1h3v3h3v7l-5 5H8l-4-6V9z M8 9v4 M12 8v5 M16 9v4',
  search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',
  sound:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',
  muted:'M3 9h4l5-5v16l-5-5H3z M16 9l5 6 M21 9l-5 6',
  rotate:'M5 7a8 8 0 1 1-1 10 M5 3v4H1',
  info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 10v7 M12 7h.01',
  play:'M7 4l13 8-13 8z',
  check:'M4 12l5 5L20 6',
  lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',
  pause:'M7 4v16 M17 4v16',
  camera:'M3 7h5l2-3h4l2 3h5v13H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8'
};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.weapon}"/></svg>`;}
const partIcon=p=>p.type==='weapon'?(p.melee?p.kind==='punch'?'punch':'sword':p.shoulder?p.kind==='missile'?'missile':'cannon':'weapon'):p.type;
let state=loadState(),tab='hangar',slot='body',group='frame',search='',catalogType='all',catalogOwned=false,catalogCount=40,selectedMission=state.mission,sector=Math.floor(state.mission/5);
let candidate=null,partSort='model',equipCount=30,partView=null;
const previewBuild=()=>candidate&&tab==='hangar'?{...state.build,[slot]:candidate}:state.build;
let battle=null,speed=1,paused=false,resultShown=false,finishAt=0,sceneKey='',lastTime=performance.now(),accumulator=0,lastHud=0,toastTimer;
const audio=new BattleAudio(state.sound);
let scene;try{scene=new MechScene($('#viewport'));}catch(e){console.warn('WebGL unavailable',e);$('#viewport').insertAdjacentHTML('afterbegin','<div class="fallback">3D表示を開始できませんでした。<br>Safariで開き直すと改善する場合があります。<br>機体構築とオートバトルは利用できます。</div>');}
$('#loading').remove();
function save(){if(!persist(state))toast('端末へ保存できません。設定からセーブを書き出せます。');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function closeSheet(){if($('#sheet').open)$('#sheet').close();partView=null;}
function sheet(html){$('#sheet-content').innerHTML=html;$('#sheet').classList.toggle('weapon-sheet',!!$('#sheet-content').querySelector('.weapon-detail-scroll'));if(!$('#sheet').open)$('#sheet').showModal();$('#sheet').scrollTop=0;$('#sheet').focus({preventScroll:true});}
function sheetHeader(eyebrow,title,subtitle=''){return `<div class="sheet-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close-button" data-action="close" aria-label="閉じる">×</button></div>`;}
function matches(p){const q=search.trim().toLowerCase();return !q||`${p.name} ${p.title} ${MAKERS[p.maker].name} ${p.kind}`.toLowerCase().includes(q);}
function baseMetrics(s){return `<div class="stat-rail"><div class="stat-cell"><small>CORE AP</small><b>${num(s.pools.body)}</b></div><div class="stat-cell ${s.overweight?'danger':''}"><small>WEIGHT / LIMIT</small><b>${num(s.weight)}<span> / ${s.capacity}</span></b></div><div class="stat-cell ${s.underpowered?'danger':''}"><small>PWR / OUTPUT</small><b>${s.draw}<span> / ${s.output}</span></b></div><div class="stat-cell"><small>MOBILITY</small><b>${s.speed.toFixed(1)}<span> m/s</span></b></div></div>`;}
function warning(s){return s.overweight||s.underpowered?`<div class="warning">${s.overweight?'積載超過：移動速度が低下しています。軽量化か脚の変更を検討してください。':''}${s.underpowered?'<br>電力不足：移動速度と攻撃頻度が低下しています。エンジンの変更を検討してください。':''}</div>`:'';}
function partSummary(p){if(p.type==='weapon')return `威力 ${p.damage}　射程 ${p.range}m`;if(p.type==='engine')return `出力 ${p.output}　冷却 ${p.cooling}`;if(p.type==='legs')return `速度 ${p.speed}　積載 ${p.capacity}`;if(p.type==='armor')return `実弾 ${p.kinetic} / 熱 ${p.thermal} / 爆 ${p.explosive}`;return `AP ${p.hp}　照準 ${signed(p.handling)}`;}
function comparison(p,current){if(!current)return '';const key=p.type==='weapon'?'damage':p.type==='engine'?'output':p.type==='legs'?'speed':'hp';const delta=p[key]-current[key];return delta?`<span class="${delta>0?'plus':'minus'}">${{damage:'威力',output:'出力',speed:'速度',hp:'AP'}[key]} ${signed(delta)}</span>`:'';}
function partRow(p,mode='equip'){
  const owned=state.inventory.includes(p.id),equipped=state.build[slot]===p.id,current=getPart(state.build[slot]);
  let action=mode==='equip'?'fit':mode==='buy'&&p.type!=='weapon'?'buy':'part';
  return `<div class="part-row ${mode==='equip'&&equipped?'equipped':''} ${mode==='equip'&&candidate===p.id?'fitting':''}" style="--rarity:${RARITY_COLORS[p.rarity]}"><button class="part-main" data-action="${action}" data-id="${p.id}" aria-label="${p.name} ${p.title}${mode==='equip'?'を試着':''}"><span class="part-icon">${icon(partIcon(p))}</span><span class="part-info"><span class="part-name">${p.name}</span>${mode==='equip'&&equipped?'<span class="part-tag">装備中</span>':''}<span class="part-title" style="display:block">${p.title}</span><span class="part-meta"><span>${partSummary(p)}</span>${mode==='equip'?comparison(p,current):''}</span><span class="part-meta"><span>${p.weight}t / 消費 ${p.draw||0}</span><span style="color:${RARITY_COLORS[p.rarity]}">${RARITIES[p.rarity]}</span></span></span>${mode==='buy'?`<span class="part-price">${num(p.price)}<small> CR</small></span>`:mode==='catalog'?`<span class="locked-label">${owned?'所持':'未回収'}</span>`:''}</button>${mode!=='catalog'?`<button class="inspect" data-action="part" data-id="${p.id}" aria-label="${p.name}の性能を見る">${icon('info')}</button>`:''}</div>`;
}
function equipRows(){const def=SLOT_DEFS.find(s=>s.id===slot),pool=state.inventory.map(getPart).filter(p=>accepts(def,p)&&matches(p)).sort((a,b)=>(b.id===state.build[slot])-(a.id===state.build[slot])||(partSort==='weight'?a.weight-b.weight:partSort==='name'?a.name.localeCompare(b.name):b.mark-a.mark)||a.name.localeCompare(b.name));return pool.length?pool.slice(0,equipCount).map(p=>partRow(p)).join('')+(pool.length>equipCount?`<button class="button wide" data-action="more-equipped">さらに30件を表示（${equipCount} / ${pool.length}）</button>`:''):'<p class="empty">該当するパーツがありません。<br>検索を変えるか、任務や補給で入手できます。</p>';}

function scrollPanelTo(selector){const panel=$('#panel'),target=panel.querySelector(selector);if(target)panel.scrollTop+=target.getBoundingClientRect().top-panel.getBoundingClientRect().top-14;}
function searchBar(extra=''){return `<div class="filterbar"><div class="search-wrap">${icon('search')}<input type="search" id="part-search" value="${escapeHTML(search)}" placeholder="パーツ名・メーカー" aria-label="パーツを検索" autocomplete="off"></div>${extra}</div>`;}
function tacticsUI(){return `<div class="section-label"><h3>戦闘プログラム</h3><span>AUTO PILOT</span></div><div class="tactics">${TACTICS.map(t=>`<button class="tactic ${state.tactic===t.id?'active':''}" data-action="tactic" data-value="${t.id}" aria-pressed="${state.tactic===t.id}">${t.name}</button>`).join('')}</div><p class="hint">${TACTICS.find(t=>t.id===state.tactic).desc}</p><div class="target-row"><label for="target-select">優先する部位</label><select id="target-select">${TARGETS.map(t=>`<option value="${t.id}" ${state.target===t.id?'selected':''}>${t.name}</option>`).join('')}</select></div>`;}
function hangarPanel(){
  const s=statsFor(previewBuild()),def=SLOT_DEFS.find(s=>s.id===slot);
  return `<div class="panel-heading"><div><span class="eyebrow">ASSEMBLY / 13 SLOTS</span><h2>機体構築</h2></div><button class="icon-button" data-action="help" aria-label="遊び方">${icon('info')}</button></div>${buildBrief(previewBuild(),state.tactic)}${fittingPanel(state.build,slot,candidate)}<div class="segmented">${[['frame','フレーム'],['weapon','武装'],['armor','装甲']].map(([id,name])=>`<button class="${id===group?'active':''}" data-action="group" data-value="${id}">${name}</button>`).join('')}</div><div class="slot-grid">${SLOT_DEFS.filter(s=>s.group===group).map(s=>{const p=getPart(state.build[s.id]);return `<button class="slot ${slot===s.id?'active':''}" data-action="slot" data-slot="${s.id}">${icon(s.type)}<span><span class="slot-label">${s.name}</span><span class="slot-code">${p?p.name:'未装備'}</span></span></button>`;}).join('')}</div><div class="section-label"><h3>${def.name}を選ぶ</h3><span>タップで試着・比較</span></div>${searchBar(`<select id="part-sort" aria-label="所持パーツの並び順"><option value="model" ${partSort==='model'?'selected':''}>モデル順</option><option value="weight" ${partSort==='weight'?'selected':''}>軽量順</option><option value="name" ${partSort==='name'?'selected':''}>型番順</option></select>`)}<div id="part-list" class="part-list">${equipRows()}</div>${def.optional&&state.build[slot]?'<div class="group-action"><button class="button small" data-action="unequip">この肩武器を外す</button></div>':''}<div class="section-divider"></div>${tacticsUI()}${diagnosticPanel(previewBuild(),state.tactic)}<div class="section-divider"></div><div class="section-label"><h3>機体カラー</h3><span>${PAINTS[state.paint].name}</span></div><div class="paint-row">${PAINTS.map((p,i)=>`<button class="paint-button ${i===state.paint?'active':''}" style="--swatch:#${(p.color??0x8d9a8a).toString(16)}" data-action="paint" data-value="${i}" aria-label="${p.name}" aria-pressed="${i===state.paint}"></button>`).join('')}</div><div class="group-action"><button class="button primary wide" data-action="tab" data-tab="missions">${icon('missions')}任務を選ぶ</button></div>`;
}
function missionPanel(){const info=missionInfo(selectedMission),enemy=enemyLoadout(selectedMission),enemyStats=statsFor(enemy),unlocked=unlockedMission(state),s=statsFor(state.build);
  return `<div class="panel-heading"><div><span class="eyebrow">CONTRACT / ${String(sector+1).padStart(2,'0')}</span><h2>${SECTORS[sector].name}</h2></div><span class="count-label">${state.completed.length} / 40</span></div><div class="sector-tabs">${SECTORS.map((x,i)=>`<button class="sector-tab ${i===sector?'active':''}" data-action="sector" data-value="${i}" ${i*5>unlocked?'disabled':''} aria-label="区域${i+1} ${x.name}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><p class="hint" style="margin-bottom:16px">${SECTORS[sector].description}</p>${Array.from({length:5},(_,step)=>{const index=sector*5+step,m=missionInfo(index),done=state.completed.includes(index);return `<button class="mission-row ${selectedMission===index?'active':''}" data-action="mission" data-value="${index}" ${index>unlocked?'disabled':''}><span class="mission-number">${String(step+1).padStart(2,'0')}</span><span class="mission-copy"><strong>${m.title}</strong><small>${m.boss?'区域ボス / ':''}報酬 ${num(m.credits)} CR ・パーツ ${m.rewards}個</small></span><span class="mission-badge">${done?icon('check'):index>unlocked?icon('lock'):m.boss?'BOSS':''}</span></button>`;}).join('')}<div class="enemy-summary"><span class="eyebrow">HOSTILE INTELLIGENCE</span><strong>敵機データ / Mk ${info.rank}</strong><div class="enemy-weapons">${[...new Set(enemyStats.weapons.map(w=>w.part.title))].map(title=>`<span>${title}</span>`).join('')}</div><div class="mission-facts"><div>胴耐久<b>${num(enemyStats.pools.body)}</b></div><div>移動速度<b>${enemyStats.speed.toFixed(1)}</b></div><div>脚タイプ<b style="font:13px inherit">${getPart(enemy.legs).title.replace('ユニット','')}</b></div></div></div><div class="armor-intel">胴装甲の軽減率 <b>実弾 ${enemyStats.resist.body.kinetic}% / 熱 ${enemyStats.resist.body.thermal}% / 爆発 ${enemyStats.resist.body.explosive}%</b></div><div class="salvage-targets"><span>優先回収系統</span><b>${info.families.map(f=>FAMILIES.find(x=>x.id===f)?.name||f).join(' / ')}</b></div>${tacticsUI()}<div class="section-divider"></div>${warning(s)}<p class="hint">出撃ごとに耐久・弾薬は全回復。敗北しても回収品と報酬の一部を持ち帰れます。</p><div class="mission-start"><button class="button primary wide" data-action="start">${icon('play')}オートバトルに出撃</button></div>`;
}
function shopPanel(){const offers=shopOffers(state);return `<div class="panel-heading"><div><span class="eyebrow">SUPPLY / SALVAGE EXCHANGE</span><h2>パーツ補給</h2></div><span class="count-label">${num(state.credits)} CR</span></div><p class="hint" style="margin-bottom:20px">回収資金で装備を購入。任務を終えると入荷が変わります。</p><div class="part-list">${offers.map(p=>partRow(p,'buy')).join('')}</div><p class="hint" style="margin-top:20px">同じパーツを左右両方に装備できます。購入したパーツは失われません。</p>`;}
function catalogPool(){return PARTS.filter(p=>(catalogType==='all'||p.type===catalogType)&&(!catalogOwned||state.inventory.includes(p.id))&&matches(p)).sort((a,b)=>Number(state.inventory.includes(b.id))-Number(state.inventory.includes(a.id))||a.maker-b.maker||a.family-b.family||a.mark-b.mark);}
function catalogRows(){const pool=catalogPool();return `${pool.length?pool.slice(0,catalogCount).map(p=>partRow(p,'catalog')).join(''):'<p class="empty">該当するパーツがありません。</p>'}${pool.length>catalogCount?`<button class="button wide load-more" data-action="more">さらに40件を表示（${Math.min(catalogCount,pool.length)} / ${pool.length}）</button>`:''}`;}
function catalogPanel(){return `<div class="panel-heading"><div><span class="eyebrow">PARTS ARCHIVE / 8 MANUFACTURERS</span><h2>パーツ図鑑</h2></div><span class="count-label">${state.inventory.length} / ${PARTS.length}</span></div><p class="hint">26系統 × 8メーカー × 8モデル。性能を調べて、次のビルドを計画できます。</p><div class="catalog-progress"><span style="width:${state.inventory.length/PARTS.length*100}%"></span></div>${searchBar(`<select class="type-filter" id="catalog-type" aria-label="パーツ部位"><option value="all">すべての部位</option>${[['body','ボディ'],['arm','腕'],['legs','脚'],['engine','エンジン'],['armor','アーマー'],['weapon','武器']].map(([id,name])=>`<option value="${id}" ${catalogType===id?'selected':''}>${name}</option>`).join('')}</select>`)}<div class="segmented"><button class="${!catalogOwned?'active':''}" data-action="owned" data-value="all">全パーツ</button><button class="${catalogOwned?'active':''}" data-action="owned" data-value="owned">所持パーツ</button></div><div id="part-list" class="part-list">${catalogRows()}</div>`;}
function render({keepScroll=false}={}){
  const scroll=$('#panel').scrollTop,s=statsFor(previewBuild());document.body.classList.toggle('mode-battle',!!battle);
  $('#credits').textContent=num(state.credits);$('#collection-count').textContent=`PARTS ${state.inventory.length} / 1664`;
  $('#sound-toggle').innerHTML=icon(state.sound?'sound':'muted');$('#sound-toggle').setAttribute('aria-pressed',String(state.sound));$('#settings').innerHTML=icon('settings');$('#settings').disabled=!!battle;
  $('#nav').innerHTML=[['hangar','格納庫','ASSEMBLY'],['missions','任務','CONTRACTS'],['shop','補給','SUPPLY'],['catalog','図鑑','ARCHIVE']].map(([id,name,en])=>`<button class="${tab===id?'active':''}" data-action="tab" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${icon(id)}<div>${name}<span>${en}</span></div></button>`).join('');
  $('#battle-hud').hidden=!battle;$('#view-tools').hidden=!!battle;$('#viewport').classList.toggle('is-fitting',!!candidate);
  if(battle){$('#scene-meta').innerHTML=`<span class="eyebrow">AUTO COMBAT / ${String(battle.index+1).padStart(2,'0')}</span><h1>${escapeHTML(battle.info.title)}</h1>`;$('#scene-status').innerHTML='<span class="scene-ready">LIVE FEED</span>';$('#scene-bottom').innerHTML=`<div class="weapon-status" id="weapon-status"></div><div class="battle-log" id="battle-log"></div><div class="combat-bottom"><div class="combat-status"><span>ENERGY<b id="battle-energy"></b></span><span>HEAT<b id="battle-heat"></b></span><span>TACTIC<b>${TACTICS.find(t=>t.id===state.tactic).name}</b></span></div><div class="battle-controls"><button class="button small" data-action="pause" id="pause-button" aria-label="戦闘を一時停止">${icon(paused?'play':'pause')}</button><button class="button small" data-action="speed" id="speed-button">${speed}×</button><button class="button small" data-action="camera" aria-label="カメラを切り替える">${icon('camera')}</button><button class="button small" data-action="skip">結果まで進める</button></div></div>`;updateHud();return;}
  $('#panel').innerHTML=tab==='hangar'?hangarPanel():tab==='missions'?missionPanel():tab==='shop'?shopPanel():catalogPanel();
  $('#panel').scrollTop=keepScroll?scroll:0;
  const mission=missionInfo(selectedMission);
  $('#scene-meta').innerHTML=tab==='missions'?`<span class="eyebrow">SECTOR ${String(mission.sector+1).padStart(2,'0')} / CONTRACT</span><h1>${mission.code}</h1><div class="scene-sub">${escapeHTML(mission.title)}</div>`:`<span class="eyebrow">HANGAR / 07</span><h1>${escapeHTML(state.name)}</h1><div class="scene-sub">${getPart(previewBuild().legs).title} / ${MAKERS[getPart(previewBuild().body).maker].name}</div>`;
  $('#scene-status').innerHTML=`<span class="scene-ready">${candidate?'FITTING PREVIEW':s.overweight||s.underpowered?'CHECK BUILD':'SYSTEM READY'}</span>${tab==='missions'?`<div style="margin-top:6px">ENEMY / MK ${mission.rank}</div>`:''}`;
  $('#scene-bottom').innerHTML=`<div class="view-hint">${icon('rotate')}ドラッグで回転 <span> / </span> ${candidate?'試着中の外観':'ASSEMBLY VIEW'}</div>${baseMetrics(s)}${tab==='hangar'?`<div class="scene-action"><span class="subtle">${state.wins}勝 / ${state.battles}戦　・　パーツ ${state.inventory.length}種</span><button class="button primary" data-action="tab" data-tab="missions">${icon('missions')}任務を選ぶ</button></div>`:''}`;
  const key=JSON.stringify([tab==='missions'?'mission':'hangar',previewBuild(),state.paint,tab==='missions'?selectedMission:null]);$('#view-tools').hidden=tab==='missions';if(scene&&key!==sceneKey){sceneKey=key;if(tab==='missions')scene.setMission(state.build,enemyLoadout(selectedMission),mission.theme,state.paint);else scene.setHangar(previewBuild(),state.paint);}
}
function showPart(id,preferred=slot,origin=''){const p=getPart(id);if(!p)return;const owned=state.inventory.includes(id),maker=MAKERS[p.maker];
  const compareSlot=p.type==='weapon'?weaponSlot(state.build,id,preferred):null;
  partView={id,slot:compareSlot,origin};
  const rows=[['重量',`${p.weight} t`],['消費電力',`${p.draw||0}`]];
  if(p.hp)rows.push(['部位耐久',p.hp]);
  if(p.type==='weapon')rows.push(['攻撃力',p.damage],['射程',`${p.minRange}–${p.range} m`],['攻撃間隔',`${p.interval} s`],['命中率',`${Math.round(p.accuracy*100)}%`],['衝撃',p.stagger],['発熱 / 射撃',p.heat],['電力 / 射撃',p.energyShot],['弾数',p.ammo||'∞'],['属性',{kinetic:'実弾',thermal:'熱',explosive:'爆発'}[p.damageType]]);
  if(p.type==='engine')rows.push(['出力',p.output],['エネルギー',p.energy],['冷却 / 秒',p.cooling],['推進倍率',`${p.thrust}×`]);
  if(p.type==='legs')rows.push(['移動速度',`${p.speed} m/s`],['最大積載',`${p.capacity} t`]);
  if(p.type==='armor')rows.push(['実弾軽減',`${p.kinetic}%`],['熱軽減',`${p.thermal}%`],['爆発軽減',`${p.explosive}%`]);
  if(p.handling)rows.push(['照準補正',signed(p.handling)]);if(p.stability)rows.push(['安定性',p.stability]);if(p.melee===1.2)rows.push(['近接倍率','1.2×']);
  const compatible=SLOT_DEFS.filter(s=>accepts(s,p));
  const specs=p.type==='weapon'?weaponComparisonPanel(state.build,compareSlot,id,true)+warning(statsFor({...state.build,[compareSlot]:id})):`<div class="detail-stats">${rows.map(([label,value])=>`<div class="detail-stat"><span>${label}</span><b>${value}</b></div>`).join('')}</div>`;
  const actions=owned?p.type==='weapon'?`<button class="button primary wide" data-action="equip-detail" data-id="${id}" data-slot="${compareSlot}" ${state.build[compareSlot]===id?'disabled':''}>${state.build[compareSlot]===id?'この部位に装備中':SLOT_DEFS.find(s=>s.id===compareSlot).name+'に交換'}</button>`:compatible.map(s=>`<button class="button secondary" data-action="equip-detail" data-id="${p.id}" data-slot="${s.id}">${s.name}に装備</button>`).join(''):shopOffers(state).some(o=>o.id===id)?`<button class="button primary wide" data-action="buy-detail" data-id="${id}" ${state.credits<p.price?'disabled':''}>${num(p.price)} CR で購入${state.credits<p.price?' / 資金不足':''}</button>`:'<p class="hint">任務の回収品や補給の入荷で入手できます。</p>';
  const detail=`${sheetHeader(origin==='purchase'?'ACQUIRED / 武器入手':origin==='reward'?'SALVAGE / 回収武器':'PART SPECIFICATION',p.name,p.title)}<span class="rarity-tag" style="--rarity:${RARITY_COLORS[p.rarity]}">${RARITIES[p.rarity]} / Mk ${p.mark}</span>${specs}<p class="hint">${maker.name} / ${maker.desc}</p>`;
  const footer=`<div class="detail-actions ${p.type==='weapon'?'compare-actions':''}">${actions}${origin==='reward'?'<button class="button secondary wide" data-action="comparison-back">回収結果に戻る</button>':''}</div>`;
  sheet(p.type==='weapon'?`<div class="weapon-detail-scroll">${detail}</div>${footer}`:detail+footer);
}
function showSettings(){sheet(`${sheetHeader('PILOT SETTINGS','機体とセーブ')}<div class="settings-block"><h3>機体名</h3><input id="mech-name" value="${escapeHTML(state.name)}" maxlength="20" aria-label="機体名" style="width:100%"></div><div class="settings-block"><h3>機体構成スロット</h3>${state.presets.map((p,i)=>`<div class="preset-row"><span>機体 ${i+1}<small style="display:block;color:var(--muted);margin-top:4px">${p?`${getPart(p.body).name} / ${getPart(p.legs).title}`:'未保存'}</small></span><button class="button small" data-action="preset-save" data-value="${i}">保存</button><button class="button small" data-action="preset-load" data-value="${i}" ${!p?'disabled':''}>読込</button></div>`).join('')}</div><div class="settings-block"><h3>セーブデータ</h3><p class="hint">この端末に自動保存。別の端末へ移す場合は書き出したファイルを読み込めます。</p><div class="save-buttons"><button class="button" data-action="export">セーブを書き出す</button><button class="button" data-action="import">セーブを読み込む</button></div></div><div class="settings-block"><button class="button wide" data-action="help">${icon('info')}遊び方・ビルドのヒント</button></div><p class="hint" style="margin-top:24px">IRON SALVAGE / ${VERSION} ・ パーツ ${PARTS.length}種類</p>`);}
function showHelp(){sheet(`${sheetHeader('FIELD MANUAL','遊び方')}<ol class="help-steps"><li><b>格納庫で組み立てる。</b> フレーム・武装・装甲の部位を選び、所持パーツをタップして試着。外観と性能差を確認してから装備します。</li><li><b>重量と電力を確認。</b> 積載超過は機動力を下げ、電力不足は攻撃頻度を下げます。</li><li><b>任務を選んで出撃。</b> 操作はオート。作戦と狙う部位を出撃前に設定します。</li><li><b>パーツを回収。</b> 入手したパーツは何度でも使用可能。同じものを左右に装備できます。</li><li><b>ビルドを改善。</b> 腕を失うと手持ち武器が停止。脚を失うと機動力が低下。胴の破壊で決着。</li></ol><div class="section-divider"></div><p class="hint">剣・パンチを使うなら「接近強襲」。長射程の銃やミサイルには「引き撃ち」。タンクと重砲には「固定砲台」が向いています。遮蔽物は直接射撃を防ぎ、ミサイルは上を通過します。</p><p class="hint" style="margin-top:14px">敗北時も少量の報酬とパーツを回収。修理代は不要です。各区域のボスを倒すと次の区域へ進めます。クリア済みの任務は何度でも再出撃できます。</p><button class="button primary wide" data-action="close" style="margin-top:24px">格納庫へ戻る</button>`);}
function equip(id,newSlot=slot){candidate=null;const def=SLOT_DEFS.find(s=>s.id===newSlot),p=getPart(id);if(!state.inventory.includes(id)||!def||!accepts(def,p))return;state.build[newSlot]=id;slot=newSlot;group=def.group;save();render({keepScroll:true});toast(`${def.name}に ${p.name} を装備`);}
function buy(id,detail=false){const p=shopOffers(state).find(p=>p.id===id);if(!p)return;if(state.credits<p.price){toast('資金が足りません。任務で回収資金を集めましょう。');return;}const target=partView?.slot;state.credits-=p.price;state.inventory.push(id);save();if(detail&&p.type!=='weapon')closeSheet();render({keepScroll:true});if(p.type==='weapon')showPart(id,target,'purchase');toast(`${p.name} を購入しました`);}
function startBattle(){candidate=null;closeSheet();selectedMission=Math.min(selectedMission,unlockedMission(state));const seed=(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0;state.pending={seed,index:selectedMission};save();battle=createBattle(state.build,selectedMission,{seed,tactic:state.tactic,target:state.target});paused=false;speed=1;accumulator=0;resultShown=false;finishAt=0;sceneKey='';scene?.setBattle(battle,state.paint);render();audio.start();}
function updateHud(){if(!battle)return;$('#weapon-status').innerHTML=weaponStatus(battle.units[0]);$('#battle-hud').innerHTML=`<div class="battle-health">${unitHealth(battle.units[0])}<div class="timer">${Math.max(0,75-Math.floor(battle.time))}<small>SECONDS</small></div>${unitHealth(battle.units[1])}</div>`;$('#battle-energy').textContent=`${Math.round(battle.units[0].energy)} / ${battle.units[0].stats.energy}`;$('#battle-heat').textContent=`${Math.round(battle.units[0].heat)}%`;$('#battle-heat').style.color=battle.units[0].heat>80?'var(--danger)':'var(--cyan)';const e=battle.log.find(e=>battle.time-e.time<3.5&&(e.type==='break'||e.type==='stagger'));$('#battle-log').textContent=paused?'PAUSED / 一時停止中':e?e.type==='break'?`${e.unit===0?'自機':'敵機'}の${{armL:'左腕',armR:'右腕',legs:'脚'}[e.slot]}が破壊された`:`${e.unit===0?'自機':'敵機'}が衝撃でよろめいた`:paused?'PAUSED / 一時停止中':'';}
function unitHealth(u){return `<div class="unit-health ${u.id===1?'enemy':''}"><div class="unit-name"><span>${u.id===0?escapeHTML(state.name):'HOSTILE / '+(battle.info.boss?'BOSS':'MK '+battle.info.rank)}</span><span>${Math.ceil(u.health.body)} AP</span></div><div class="hp-track"><span style="width:${u.health.body/u.stats.pools.body*100}%"></span></div><div class="limbs">${[['armL','L ARM'],['armR','R ARM'],['legs','LEGS']].map(([key,name])=>`<span class="${u.health[key]<=0?'destroyed':''}">${name} ${Math.ceil(u.health[key]/u.stats.pools[key]*100)}%</span>`).join('')}</div></div>`;}
function finishBattle(){if(finishAt)return;const result=settleBattle(state,battle.result,battle.index,battle.seed);if(result){save();$('#credits').textContent=num(state.credits);$('#collection-count').textContent=`PARTS ${state.inventory.length} / 1664`;audio.result(result.won);}finishAt=performance.now()+950;}
function showResult(){partView=null;resultShown=true;const r=state.lastResult;if(!r)return;sheet(`<span class="eyebrow">CONTRACT ${String(r.index+1).padStart(2,'0')} / COMPLETE</span><h2 class="result-title ${!r.won?'defeat':''}">${r.won?'VICTORY':'DEFEAT'}</h2><p class="scene-sub">${escapeHTML(missionInfo(r.index).title)} ${r.timeout?' / 時間判定':''}</p><div class="result-facts"><div><small>戦闘時間</small><b>${r.time}<small style="display:inline"> s</small></b></div><div><small>獲得資金</small><b>+${num(r.credits)}</b></div><div><small>胴の残存耐久</small><b>${r.health}%</b></div></div><div class="section-label"><h3>回収したパーツ</h3><span>武器は性能比較</span></div><div class="reward-list">${r.drops.map(drop=>{const p=getPart(drop.id);return `<button class="reward-card" data-action="${p.type==='weapon'?'reward-compare':'reward-fit'}" data-id="${p.id}" aria-label="回収した${p.name}${p.type==='weapon'?'の性能を比較':'を試着'}" style="--rarity:${RARITY_COLORS[p.rarity]}"><span class="part-icon">${icon(partIcon(p))}</span><div><strong>${p.name}</strong><small>${p.title} / ${RARITIES[p.rarity]}</small>${p.type==='weapon'?weaponSalvageSummary(state.build,p.id):''}</div><span class="reward-new">${drop.duplicate?'所持済':'NEW'}<small>${p.type==='weapon'?'比較':'試着'}</small></span></button>`;}).join('')}</div>${debrief(r,battle.units[0].build,battle.units[0].tactic)}<p class="result-note">${r.won?state.completed.length===40?'全40任務を制圧しました。再出撃して特装パーツを集め、機体を追求できます。':'回収したパーツを格納庫で試着できます。任務一覧から次の出撃を選びましょう。':'機体を回収しました。パーツは失われません。武装や作戦を変えて再挑戦できます。'}</p><div class="result-actions"><button class="button secondary" data-action="result-hangar">機体を組み替える</button><button class="button primary" data-action="${r.won?'result-next':'retry'}">${r.won?'任務を選ぶ':'再挑戦'}</button></div>`);}
function leaveBattle(nextTab='hangar'){closeSheet();battle=null;paused=false;finishAt=0;accumulator=0;sceneKey='';tab=nextTab;selectedMission=state.mission;sector=Math.floor(selectedMission/5);render();}

document.addEventListener('click',async e=>{
  const button=e.target.closest('button');if(!button||button.disabled)return;audio.start();
  if(button.id==='settings'){showSettings();return;}if(button.id==='sound-toggle'){state.sound=!state.sound;audio.setEnabled(state.sound);save();button.innerHTML=icon(state.sound?'sound':'muted');button.setAttribute('aria-pressed',String(state.sound));return;}
  const action=button.dataset.action,id=button.dataset.id,value=button.dataset.value;
  switch(action){
    case 'tab':if(battle)break;candidate=null;tab=button.dataset.tab;search='';if(tab==='missions'){selectedMission=state.mission;sector=Math.floor(selectedMission/5);}render();break;
    case 'group':candidate=null;equipCount=30;group=value;slot=SLOT_DEFS.find(s=>s.group===group).id;search='';render();break;
    case 'slot':candidate=null;equipCount=30;slot=button.dataset.slot;search='';render({keepScroll:true});scrollPanelTo('.filterbar');break;
    case 'fit':candidate=state.build[slot]===id?null:id;render({keepScroll:true});scrollPanelTo('.fitting-panel');break;
    case 'apply-fit':if(candidate)equip(candidate);break;
    case 'cancel-fit':candidate=null;render({keepScroll:true});break;
    case 'view-reset':if(scene){scene.angle=.52;scene.zoom=1;scene.dirty=true;}break;
    case 'view-zoom':if(scene){scene.zoom=Math.max(.72,Math.min(1.35,scene.zoom+Number(value)));scene.dirty=true;}break;
    case 'equip-detail':if(battle)leaveBattle('hangar');else closeSheet();tab='hangar';search='';equip(id,button.dataset.slot);break;
    case 'compare-slot':showPart(id,button.dataset.slot,partView?.origin);break;
    case 'comparison-back':showResult();break;
    case 'reward-compare':showPart(id,weaponSlot(state.build,id),'reward');break;
    case 'unequip':if(SLOT_DEFS.find(s=>s.id===slot).optional){state.build[slot]=null;save();render({keepScroll:true});}break;
    case 'part':showPart(id);break;
    case 'buy':buy(id);break;
    case 'buy-detail':buy(id,true);break;
    case 'tactic':state.tactic=value;save();render({keepScroll:true});break;
    case 'paint':state.paint=Number(value);save();render({keepScroll:true});break;
    case 'sector':sector=Number(value);selectedMission=Math.min(sector*5,unlockedMission(state));render();break;
    case 'mission':selectedMission=Math.min(Number(value),unlockedMission(state));state.mission=selectedMission;save();render({keepScroll:true});break;
    case 'owned':catalogOwned=value==='owned';catalogCount=40;render();break;
    case 'more-equipped':equipCount+=30;$('#part-list').innerHTML=equipRows();break;
    case 'reward-fit':leaveBattle('hangar');slot=SLOT_DEFS.find(s=>accepts(s,getPart(id))).id;group=SLOT_DEFS.find(s=>s.id===slot).group;candidate=id;search='';render();scrollPanelTo('.fitting-panel');break;
    case 'more':catalogCount+=40;$('#part-list').innerHTML=catalogRows();break;
    case 'start':startBattle();break;
    case 'pause':if(!battle||battle.result)break;paused=!paused;button.innerHTML=icon(paused?'play':'pause');button.classList.toggle('active',paused);button.setAttribute('aria-label',paused?'戦闘を再開':'戦闘を一時停止');updateHud();break;
    case 'speed':speed=speed===1?2:speed===2?4:1;button.textContent=`${speed}×`;break;
    case 'camera':if(scene){scene.cameraMode=(scene.cameraMode+1)%3;scene.dirty=true;button.classList.toggle('active',!!scene.cameraMode);toast(['戦闘カメラ','戦術俯瞰カメラ','低い追従カメラ'][scene.cameraMode]);}break;
    case 'skip':if(battle&&!battle.result){paused=false;fastForward(battle);scene?.consumeEvents(battle.events);updateHud();finishBattle();finishAt=performance.now()+350;}break;
    case 'result-hangar':leaveBattle('hangar');break;
    case 'result-next':leaveBattle('missions');break;
    case 'retry':{const index=battle.index;leaveBattle('missions');selectedMission=index;startBattle();break;}
    case 'help':showHelp();break;
    case 'close':if(partView?.origin==='reward')showResult();else if(battle?.result)leaveBattle();else closeSheet();break;
    case 'preset-save':state.presets[Number(value)]={...state.build};save();showSettings();toast(`機体 ${Number(value)+1} に構成を保存`);break;
    case 'preset-load':candidate=null;if(state.presets[Number(value)]){state.build={...state.presets[Number(value)]};save();closeSheet();tab='hangar';render();toast(`機体 ${Number(value)+1} を読み込みました`);}break;
    case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mech-battle-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('セーブデータを書き出しました');break;}
    case 'import':$('#import-file').click();break;
  }
});
$('#panel').addEventListener('input',e=>{if(e.target.id==='part-search'){search=e.target.value;catalogCount=40;equipCount=30;$('#part-list').innerHTML=tab==='catalog'?catalogRows():equipRows();}});
$('#panel').addEventListener('change',e=>{if(e.target.id==='part-sort'){partSort=e.target.value;$('#part-list').innerHTML=equipRows();}if(e.target.id==='target-select'){state.target=e.target.value;save();}if(e.target.id==='catalog-type'){catalogType=e.target.value;catalogCount=40;$('#part-list').innerHTML=catalogRows();}});
$('#sheet').addEventListener('input',e=>{if(e.target.id==='mech-name'){state.name=e.target.value||'CINDER-01';save();$('#scene-meta h1').textContent=state.name;}});
$('#sheet').addEventListener('cancel',e=>{if(partView?.origin==='reward'){e.preventDefault();showResult();}else if(battle?.result){e.preventDefault();leaveBattle();}});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){if(partView?.origin==='reward')showResult();else if(battle?.result)leaveBattle();else closeSheet();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>2000000)throw new Error('セーブファイルが大きすぎます');const parsed=JSON.parse(await f.text());candidate=null;state=normalizeState(parsed);save();audio.setEnabled(state.sound);closeSheet();tab='hangar';selectedMission=state.mission;sector=Math.floor(selectedMission/5);sceneKey='';render();toast('セーブを読み込みました');}catch(error){toast(error.message||'セーブを読み込めませんでした');}e.target.value='';});

document.addEventListener('visibilitychange',()=>{lastTime=performance.now();accumulator=0;});
function frame(now){const dt=Math.min(.1,(now-lastTime)/1000);lastTime=now;if(!document.hidden){if(battle&&!paused&&!battle.result){accumulator+=dt*speed;let steps=0;while(accumulator>=1/30&&steps++<15&&!battle.result){tick(battle,1/30);scene?.consumeEvents(battle.events);audio.events(battle.events);accumulator-=1/30;}if(battle.result)finishBattle();audio.update(battle);}scene?.render(paused?0:dt,battle);if(battle&&now-lastHud>110){lastHud=now;updateHud();}if(battle?.result&&!resultShown&&now>=finishAt)showResult();}requestAnimationFrame(frame);}
render();save();requestAnimationFrame(frame);
if('serviceWorker' in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
// Read-only diagnostics for reproducible playtests; no save or progression mutations.
window.__MECH_BATTLE__={getSnapshot:()=>({version:VERSION,tab,parts:PARTS.length,inventory:state.inventory.length,credits:state.credits,build:{...state.build},stats:statsFor(state.build),mission:state.mission,completed:[...state.completed],battle:battle?{time:battle.time,result:battle.result,units:battle.units.map(u=>({health:{...u.health},x:u.x,z:u.z,heat:u.heat}))}:null})};
